1	/**
2	 * 城市浮生记 v2 — 真随机概率系统
3	 *
4	 * ======================== 设计哲学 ========================
5	 *
6	 * ## 核心原则：独立真随机（True Random）
7	 *
8	 * 游戏中的所有概率判定在数学上完全独立。不存在：
9	 * - ❌ PRD（伪随机分布）：随着失败次数增加概率（如 Dota 2 暴击）
10	 * - ❌ 保底机制：保证 N 次内必定成功（如 Gacha 游戏）
11	 * - ❌ 隐藏修正：根据玩家状态暗中调整概率（如 XCOM 低难度）
12	 * - ❌ 双骰平均：显示 80% 实际 85%（如 Fire Emblem "True Hit"）
13	 *
14	 * 每一次 Random.chance() 调用都是独立的：上一次的结果不影响下一次。
15	 *
16	 * ## 为什么选择真随机？
17	 *
18	 * 1. 数学纯净 —— 每次掷骰都是独立事件，概率就是它声称的值
19	 * 2. 不可预测 —— 无法通过"垫刀"或"垫步"操纵系统
20	 * 3. 真实感 —— 现实生活中的随机就是真随机（没有保底）
21	 * 4. 策略深度 —— 真正的风险管理：玩家需要备选方案，而非依赖概率修正
22	 *
23	 * ## 研究参考（2026年调研）
24	 *
25	 * 参考自 6 款顶级游戏的真随机/伪随机设计：
26	 *
27	 * | 游戏 | 方案 | 对我们的启示 |
28	 * |------|------|-------------|
29	 * | XCOM | 显示即真实，低难度暗加命中 | 透明但残酷 → 提供备选方案而非保底 |
30	 * | Fire Emblem | True Hit 双骰系统 | ❌ 不采用——违背透明度原则 |
31	 * | Dota 2 | PRD 递增 + 真随机混合 | 技能依赖类可用 PRD，外围层用真随机 |
32	 * | Darkest Dungeon | 核心战斗真随机 + 压力固定检定 | 容错冗余（4人队→6:2）是真随机游戏的最佳实践 |
33	 * | Slay the Spire | 牌组真随机 Fisher-Yates | RNG 应该创造选择，而非决定结果 |
34	 * | Hades | 操作层确定性，外围层加权随机 | 越靠近核心操作，越少 RNG |
35	 *
36	 * 详见：游戏百科"随机系统"条目 / research note
37	 *
38	 * ## 真随机的游戏设计补偿（非概率层面）
39	 *
40	 * 真随机意味着会有极端情况（90% 连续失败 3 次），游戏为此提供：
41	 * - 多个独立决策机会 → 分散风险，而非依赖单次判定
42	 * - 信息透明 → 玩家看到真实的概率，做出知情决策
43	 * - 备选方案 → 失败不是终点，总有其他出路
44	 * - 容错缓冲 → 体力/金钱/人脉多维值提供失败缓冲（借鉴 Darkest Dungeon）
45	 *
46	 * ======================== 科学累积系统 ========================
47	 *
48	 * 以下系统使用累积/渐进模型，因为它们在科学上具有累积性质。
49	 * 这些不属于"概率修正"，而是独立于概率系统的自然机制：
50	 *
51	 * | 系统 | 累积方式 | 科学依据 |
52	 * |------|---------|---------|
53	 * | 技能熟练度 | 每次实践 +XP | 神经科学：重复 → 髓鞘化 → 技能提升 |
54	 * | 疾病恶化 | severity 随时间累积 | 病理学：疾病进程是累积的 |
55	 * | 天气连续性 | 30% 延续昨日天气 | 气象学：大气状态存在惯性（马尔可夫链） |
56	 * | 市场趋势 | 价格动量/均值回归 | 金融学：趋势 + 波动 + 均值回归 |
57	 * | 疲劳积累 | 随时间增加，休息减少 | 生理学：疲劳是代谢产物累积 |
58	 * | NPC 好感度 | 多次互动累积 | 心理学：信任建立在重复积极互动上 |
59	 * | 投资复利 | 本息累积计算 | 金融学：复利效应 |
60	 * | 舒适度 | 住所+衣物+环境综合 | 物理学/工程学：多因素累积影响 |
61	 * | 压力系统 | 固定检定阈值 | 借鉴 Darkest Dungeon：压力累积→固定检定点 |
62	 *
63	 * 这些系统与 Random 模块无关，它们已经有自己独立的累积逻辑。
64	 *
65	 * ======================== 使用规范 ========================
66	 *
67	 * 游戏中所有随机判定必须通过 Random.* API，禁止使用裸 Math.random()。
68	 * 规则：
69	 * - 概率判定（if/ternary）→ Random.chance(p)
70	 * - 数组随机取 → Random.fromArray(arr)
71	 * - 整数范围 → Random.int(min, max)
72	 * - 浮点数范围 → Random.float(min, max)
73	 * - 洗牌/抽N → Random.shuffle / Random.pickN
74	 * - 加权选择 → Random.weighted
75	 * - 多分支概率 → Random.multichance
76	 * - 正态分布波动 → Random.gaussian
77	 */
78	(function () {
79	  "use strict";
80	
81	  // ====== 命名空间 ======
82	  const Random = {
83	    VERSION: "2.0.0",
84	    _seed: null,
85	    _useSeed: false,
86	  };
87	
88	  // ====== 内部统一随机源 ======
89	  // 使用 Math.random() 作为底层源。游戏不依赖可预测性/种子。
90	  // 若未来需要种子化（如录像回放），在此处替换即可。
91	  const _rng = function () {
92	    return Math.random();
93	  };
94	
95	  // ====== 核心 API ======
96	
97	  /**
98	   * 真随机概率判定
99	   *
100	   * 每次调用完全独立，数学期望严格等于 probability。
101	   * 没有任何形式的保底、修正、或概率递增。
102	   *
103	   * @param {number} p - 成功概率 0.0 ~ 1.0
104	   * @returns {boolean} true = 成功
105	   *
106	   * @example
107	   * if (Random.chance(0.3)) { applyInjury(); }
108	   * if (Random.chance(0.05)) { triggerRareEvent(); }
109	   */
110	  Random.chance = function (p) {
111	    if (p <= 0) return false;
112	    if (p >= 1) return true;
113	    return _rng() < p;
114	  };
115	
116	  /**
117	   * 生成 [min, max] 范围内的随机整数（包含两端）
118	   *
119	   * @param {number} min - 最小值（包含）
120	   * @param {number} max - 最大值（包含）
121	   * @returns {number} 随机整数
122	   *
123	   * @example
124	   * const dice = Random.int(1, 6);
125	   * const idx = Random.int(0, arr.length - 1);
126	   */
127	  Random.int = function (min, max) {
128	    min = Math.ceil(min);
129	    max = Math.floor(max);
130	    if (min > max) return min;
131	    return Math.floor(_rng() * (max - min + 1)) + min;
132	  };
133	
134	  /**
135	   * 生成 [min, max) 范围内的随机浮点数
136	   *
137	   * @param {number} min - 最小值（包含）
138	   * @param {number} max - 最大值（不包含）
139	   * @returns {number} 随机浮点数
140	   *
141	   * @example
142	   * const gain = Random.float(0.5, 1.5);
143	   * const noise = Random.float(-0.1, 0.1);
144	   */
145	  Random.float = function (min, max) {
146	    return _rng() * (max - min) + min;
147	  };
148	
149	  /**
150	   * 从数组中随机选择一个元素
151	   *
152	   * @param {Array} arr - 源数组
153	   * @returns {*|null} 随机元素，数组为空时返回 null
154	   *
155	   * @example
156	   * const color = Random.fromArray(["红", "绿", "蓝"]);
157	   * const evt = Random.fromArray(availableEvents);
158	   */
159	  Random.fromArray = function (arr) {
160	    if (!arr || arr.length === 0) return null;
161	    return arr[Math.floor(_rng() * arr.length)];
162	  };
163	
164	  /**
165	   * 从数组中随机选择 n 个不重复的元素
166	   *
167	   * @param {Array} arr - 源数组
168	   * @param {number} n - 选择数量
169	   * @returns {Array} 随机子集（打乱顺序）
170	   *
171	   * @example
172	   * const threeCards = Random.pickN(deck, 3);
173	   * const dailyEvents = Random.pickN(eventPool, 2);
174	   */
175	  Random.pickN = function (arr, n) {
176	    if (!arr || arr.length === 0) return [];
177	    const count = Math.min(n, arr.length);
178	    const shuffled = Random.shuffle([...arr]);
179	    return shuffled.slice(0, count);
180	  };
181	
182	  /**
183	   * Fisher-Yates 洗牌算法（原地或返回新数组）
184	   *
185	   * @param {Array} arr - 要洗牌的数组
186	   * @param {boolean} [inPlace=false] - 是否原地修改
187	   * @returns {Array} 洗牌后的数组
188	   */
189	  Random.shuffle = function (arr, inPlace) {
190	    const result = inPlace ? arr : [...arr];
191	    for (let i = result.length - 1; i > 0; i--) {
192	      const j = Math.floor(_rng() * (i + 1));
193	      var tmp = result[i];
194	      result[i] = result[j];
195	      result[j] = tmp;
196	    }
197	    return result;
198	  };
199	
200	  /**
201	   * 加权随机选择
202	   *
203	   * 根据权重数组从元素数组中随机选择。
204	   *
205	   * @param {Array} items - 元素数组
206	   * @param {Array|Function} weightFn - 权重数组或返回权重的函数
207	   * @returns {*|null} 选中的元素
208	   *
209	   * @example
210	   * const news = Random.weighted(newsEvents, evt => evt.weight);
211	   * const weather = Random.weighted(weatherTypes, t => t.probability);
212	   */
213	  Random.weighted = function (items, weightFn) {
214	    if (!items || items.length === 0) return null;
215	
216	    var weights =
217	      typeof weightFn === "function"
218	        ? (function () {
219	            var w = [];
220	            for (var i = 0; i < items.length; i++) {
221	              w.push(weightFn(items[i]));
222	            }
223	            return w;
224	          })()
225	        : weightFn;
226	
227	    var totalWeight = 0;
228	    for (var i = 0; i < weights.length; i++) {
229	      totalWeight += weights[i];
230	    }
231	    if (totalWeight <= 0) return items[0];
232	
233	    var roll = _rng() * totalWeight;
234	    for (var i = 0; i < items.length; i++) {
235	      roll -= weights[i];
236	      if (roll <= 0) return items[i];
237	    }
238	    return items[items.length - 1];
239	  };
240	
241	  /**
242	   * 范围概率判定（多分支随机）
243	   *
244	   * 传入一个概率分段数组，返回命中的段索引。
245	   * 概率数组的和应 <= 1，剩余为"其他"情况。
246	   *
247	   * @param {number[]} probabilities - 概率分段数组（如 [0.3, 0.2, 0.1]）
248	   * @returns {number} 命中的段索引（0-based），未命中返回 -1
249	   *
250	   * @example
251	   * const r = Random.multichance([0.3, 0.2, 0.1]);
252	   * // r=0(A), 1(B), 2(C), -1(无)
253	   */
254	  Random.multichance = function (probabilities) {
255	    var roll = _rng();
256	    var cumulative = 0;
257	    for (var i = 0; i < probabilities.length; i++) {
258	      cumulative += probabilities[i];
259	      if (roll < cumulative) return i;
260	    }
261	    return -1;
262	  };
263	
264	  /**
265	   * 检查今日是否已触发过某类随机事件（防刷）
266	   *
267	   * 这不是"概率修正"——它是防止同一个事件在同一天内重复触发（逻辑去重）。
268	   *
269	   * @param {Object} state - 游戏状态（需有 state._randomDailyEvents）
270	   * @param {string} eventKey - 事件唯一标识
271	   * @param {number} [maxPerDay=1] - 每天最大触发次数
272	   * @returns {boolean} true = 可以触发
273	   */
274	  Random.canTriggerToday = function (state, eventKey, maxPerDay) {
275	    if (maxPerDay === undefined) maxPerDay = 1;
276	    if (!state._randomDailyEvents) state._randomDailyEvents = {};
277	    // 注意：state.player.day 可能在不同项目中有不同的路径
278	    var day = (state.player && state.player.day) || state.day || 0;
279	    var key = day + ":" + eventKey;
280	    if (!state._randomDailyEvents[key]) {
281	      state._randomDailyEvents[key] = 0;
282	    }
283	    if (state._randomDailyEvents[key] >= maxPerDay) return false;
284	    state._randomDailyEvents[key]++;
285	    return true;
286	  };
287	
288	  /**
289	   * 高斯（正态）分布随机数
290	   *
291	   * 用于需要"自然波动"而非均匀分布的场景
292	   * （如价格波动、属性增长），但核心仍然是真随机采样。
293	   *
294	   * @param {number} mean - 均值
295	   * @param {number} stdDev - 标准差
296	   * @returns {number} 符合正态分布的随机数
297	   *
298	   * @example
299	   * const priceNoise = Random.gaussian(0, 0.05);
300	   * const heightDist = Random.gaussian(170, 10);
301	   */
302	  Random.gaussian = function (mean, stdDev) {
303	    var u1 = 0,
304	      u2 = 0;
305	    while (u1 === 0) u1 = _rng();
306	    while (u2 === 0) u2 = _rng();
307	    var z0 = Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2.0 * Math.PI * u2);
308	    return z0 * stdDev + mean;
309	  };
310	
311	  // ====== 常用便捷速记 ======
312	
313	  /**
314	   * 掷骰子（DnD 风格）
315	   *
316	   * @param {number} sides - 骰子面数
317	   * @param {number} [times=1] - 掷骰次数
318	   * @returns {number|number[]} 一次掷骰返回点数，多次返回数组
319	   *
320	   * @example
321	   * Random.d(6)    // 1d6 → 1-6
322	   * Random.d(20)   // 1d20 → 1-20
323	   * Random.d(6, 3) // 3d6 → [3, 5, 1]
324	   */
325	  Random.d = function (sides, times) {
326	    if (times === undefined || times === 1) {
327	      return Random.int(1, sides);
328	    }
329	    var results = [];
330	    for (var i = 0; i < times; i++) {
331	      results.push(Random.int(1, sides));
332	    }
333	    return results;
334	  };
335	
336	  /**
337	   * 百分比骰子 (d100)
338	   *
339	   * @returns {number} 1-100 的随机整数
340	   *
341	   * @example
342	   * if (Random.percent() <= 30) { ... }
343	   */
344	  Random.percent = function () {
345	    return Random.int(1, 100);
346	  };
347	
348	  // ====== "运气测试" — 连续判定工具 ======
349	
350	  /**
351	   * 连续 N 次独立真随机判定
352	   *
353	   * @param {number} p - 单次成功概率
354	   * @param {number} n - 判定次数
355	   * @returns {number} 成功次数（0 ~ n）
356	   *
357	   * @example
358	   * // 10 次 30% 判定，返回成功次数
359	   * var successes = Random.trials(0.3, 10);
360	   */
361	  Random.trials = function (p, n) {
362	    var count = 0;
363	    for (var i = 0; i < n; i++) {
364	      if (Random.chance(p)) count++;
365	    }
366	    return count;
367	  };
368	
369	  // ====== 统计与调试工具 ======
370	
371	  /**
372	   * 运行 N 次随机判定，返回统计结果（仅调试用）
373	   *
374	   * @param {number} probability - 期望概率
375	   * @param {number} trials - 试验次数
376	   * @returns {Object} 统计结果
377	   */
378	  Random.simulate = function (probability, trials) {
379	    var successes = 0;
380	    for (var i = 0; i < trials; i++) {
381	      if (Random.chance(probability)) successes++;
382	    }
383	    return {
384	      trials: trials,
385	      successes: successes,
386	      actualRate: successes / trials,
387	      expectedRate: probability,
388	      deviation: Math.abs(successes / trials - probability),
389	    };
390	  };
391	
392	  /**
393	   * 打印统计报告到控制台
394	   *
395	   * @param {number} probability - 期望概率
396	   * @param {number} [trials=10000] - 试验次数
397	   */
398	  Random.report = function (probability, trials) {
399	    if (trials === undefined) trials = 10000;
400	    var result = Random.simulate(probability, trials);
401	    console.log(
402	      "Random Report: P=" +
403	        probability +
404	        " N=" +
405	        result.trials +
406	        " -> " +
407	        (result.actualRate * 100).toFixed(2) +
408	        "%" +
409	        " (dev=" +
410	        (result.deviation * 100).toFixed(2) +
411	        "%)",
412	    );
413	  };
414	
415	  // ====== 导出（全局命名空间） ======
416	  window.Random = Random;
417	})();
418

